    {
      "feature": "DEYE",
      "score": 0.53,
      "rationale": "Vision difficulty is semantically relevant to disability-related coverage but narrower than overall disability status."
    },
    {
      "feature": "DREM",
      "score": 0.60,
      "rationale": "Cognitive difficulty is a stable indicator of disability-related public coverage needs and eligibility."
    },
    {
      "feature": "PINCP",
      "score": 0.90,
      "rationale": "Personal income is central to Medicaid and subsidy eligibility and should remain highly predictive across states."
    },
    {
      "feature": "ESR",
      "score": 0.76,
      "rationale": "Employment status strongly affects access to employer insurance and public coverage eligibility."
    },
    {
      "feature": "ST",
      "score": 0.08,
      "rationale": "State encodes geography and policy environment directly, making it highly brittle for out-of-distribution state generalization."
    },
    {
      "feature": "FER",
      "score": 0.24,
      "rationale": "Recent fertility can relate to pregnancy or postpartum Medicaid coverage but applies narrowly and conditionally."
    },
    {
      "feature": "RAC1P",
      "score": 0.18,
      "rationale": "Race may correlate with coverage disparities but is a sensitive demographic shortcut with poor semantic robustness."
    }
  ]
